import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        List<String> spells = List.of("Fireball", "Frost", "Fire Storm",
                                      "Thunder", "Frost Nova", "Flare");

        // Part 1: groupingBy first character
        Map<Character, List<String>> grouped = spells.stream()
            .collect(Collectors.groupingBy(s -> s.charAt(0)));

        // TODO: iterate grouped.entrySet() and print each entry e.g. "F=[Fireball, ...]"
        for (var entry : grouped.entrySet()) {
            System.out.println(entry.getKey() + "=" + entry.getValue());
        }

        // Part 2: partitioningBy length > 5
        Map<Boolean, List<String>> partition = spells.stream()
            // TODO: collect using partitioningBy(s -> s.length() > 5)
            .collect(Collectors.partitioningBy(s -> s.length() > 5));

        System.out.println("Long spells: " + partition.get(true).size());
    }
}

