import java.util.*;
import java.util.stream.*;
public class Main {
    public static void main(String[] args) {
        List<String> words = List.of("cat", "car", "bat", "bar");
        Map<Boolean, Long> counts = words.stream()
            .collect(Collectors.partitioningBy(
                s -> s.startsWith("c"),
                Collectors.counting()));
        System.out.println("c-words: " + counts.get(true));
        System.out.println("others: " + counts.get(false));
    }
}

import java.util.*;
import java.util.stream.*;
public class Main {
    public static void main(String[] args) {
        List<String> spells = List.of("Fireball", "Frost", "Fireball");
        Map<String, String> nameMap = spells.stream()
            .collect(Collectors.toMap(
                s -> s,         // key: spell name
                s -> s.toUpperCase() // value: uppercase
            ));
    }
}

